import{createLogger,logError}from"#internal/logging.js";import{toError}from"#shared/errors.js";import{startWorkflowOnCurrentDeployment,workflowToolRunWorkflowReference}from"#execution/workflow-runtime.js";import{registerWorkflowToolRun}from"#harness/workflow-tool-runs.js";import{createRuntimeToolResultFromValue}from"#harness/action-result-helpers.js";const log=createLogger(`execution.workflow-tool-run`);async function startWorkflowToolRun(e){let t=e.entry.entryPoint===`execute`?crypto.randomUUID():taskRunHookToken(e.session.id,e.entry.taskId);return{hookToken:t,runId:(await startWorkflowOnCurrentDeployment(workflowToolRunWorkflowReference,[{...e,hookToken:t}])).runId}}function taskRunHookToken(e,t){return`eve:task:${e}:${t}`}async function startWorkflowToolCallRun(e,t){let{prestarted:n}=e;if(n!==void 0){if(!isSameRunEntry(n.entry,t))throw Error(`Call "${e.task.callId}" was started for a different entry point.`);return await n.run}let{task:r,batchEvent:i,session:a}=e;return await startWorkflowToolRun({agentContext:e.agentContext,callId:r.callId,entry:t,executeInput:r.executeInput,input:r.input,owner:e.owner,session:{auth:e.auth,id:a.sessionId,parent:e.parentSession,turn:{id:i.turnId,sequence:i.sequence}},stepIndex:i.stepIndex,toolName:r.toolName,workflowId:r.workflowId})}function isSameRunEntry(e,t){return e.entryPoint===`execute`||t.entryPoint===`execute`?e.entryPoint===t.entryPoint:e.entryPoint===t.entryPoint&&e.taskId===t.taskId}async function startWorkflowTask(e){let{task:t,batchEvent:n,session:r}=e;try{let i=await startWorkflowToolCallRun(e,{entryPoint:`execute`});return{session:registerWorkflowToolRun(r,{callId:t.callId,origin:{turnId:n.turnId,stepIndex:n.stepIndex},address:i,toolName:t.toolName})}}catch(e){return logError(log,`workflow tool run failed to start`,e,{callId:t.callId,toolName:t.toolName}),{result:startFailureResult(t,e),session:r}}}function startFailureResult(e,t){return createRuntimeToolResultFromValue({callId:e.callId,isError:!0,output:toError(t),toolName:e.toolName})}export{startFailureResult,startWorkflowTask,startWorkflowToolCallRun,startWorkflowToolRun};